{
  "status": "SUPPORTED",
  "task_summary": "Set up two refreshment stations near the seating area and place the remote control on a surface accessible to both people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A place for a drink and food item for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["plate", "cup", "bowl", "mug"],
        "required_properties": ["holds_refreshment"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller", "handset"],
        "required_properties": ["operates_television"]
      },
      {
        "id": "accessible_surface",
        "entity_kind": "REGION",
        "function": "A flat area where the remote can be easily reached.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "shelf", "side_table"],
        "required_properties": ["flat", "supports_objects"]
      },
      {
        "id": "seating_spot",
        "entity_kind": "FIXED_TARGET",
        "function": "A place where a person sits to watch television.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["chair", "sofa", "armchair"],
        "required_properties": ["supports_person", "faces_screen"]
      }
    ],
    "functional_relations": [
      {
        "id": "nearby_seating",
        "relation": "Each refreshment setting must be located near a seating spot.",
        "participant_roles": [
          "refreshment_setting",
          "seating_spot"
        ]
      ,
        "required": true
      },
      {
        "id": "on_accessible_surface",
        "relation": "The entertainment control must be placed on the accessible surface.",
        "participant_roles": [
          "entertainment_control",
          "accessible_surface"
        ]
      ,
        "required": true
      },
      {
        "id": "accessible_to_both",
        "relation": "The accessible surface must be reachable from both seating spots.",
        "participant_roles": [
          "accessible_surface",
          "seating_spot"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment_settings",
        "operation": "Place a refreshment setting for each person.",
        "participant_roles": [
          "refreshment_setting"
        ,
          "seating_spot"
        ],
        "operation_count": 2
      },
      {
        "id": "place_entertainment_control",
        "operation": "Move the entertainment control to the accessible surface.",
        "participant_roles": [
          "entertainment_control",
          "accessible_surface"
        ],
        "operation_count": 1
      }
    ]
  }
